using Microsoft.AspNetCore.Identity; using Microsoft.AspNetCore.Mvc; using SphotoApp.Web.Models; using SphotoApp.Web.ViewModels; namespace SphotoApp.Web.Controllers; public class AccountController(SignInManager<ApplicationUser> signIn):Controller { [HttpGet] public IActionResult Login()=>View(); [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Login(LoginVm m){if(!ModelState.IsValid)return View(m);var r=await signIn.PasswordSignInAsync(m.Username,m.Password,m.RememberMe,false);if(r.Succeeded)return RedirectToAction("Index","Home");ModelState.AddModelError("","Tên đăng nhập hoặc mật khẩu không đúng.");return View(m);} [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Logout(){await signIn.SignOutAsync();return RedirectToAction(nameof(Login));} }
